    "\u{1F472}": "\u6234\u4E2D\u5F0F\u5E3D\u5605\u7537\u4EBA \u4E2D\u5F0F\u5E3D \u4EBA\u7269 \u5E3D \u5E3D\u5B50 \u74DC\u76AE\u5E3D \u7537\u58EB \u7537\u6027",
    "\u{1F472}\u{1F3FB}": "\u6234\u4E2D\u5F0F\u5E3D\u5605\u7537\u4EBA\uFF1A\u767D\u76AE\u819A \u4E2D\u5F0F\u5E3D \u4EBA\u7269 \u5E3D \u5E3D\u5B50 \u6234\u4E2D\u5F0F\u5E3D\u5605\u7537\u4EBA \u74DC\u76AE\u5E3D \u7537\u58EB \u7537\u6027 \u767D\u76AE\u819A",
