    "\u{1F483}\u{1F3FC}": "\u8DF3\u821E\u5605\u5973\u4EBA\uFF1A\u9EC3\u76AE\u819A disco party \u4EBA\u7269 \u512A\u96C5 \u5973\u4EBA \u5973\u58EB \u5973\u6027 \u63A2\u6208 \u6CD5\u862D\u660E\u6B4C \u821E\u8E48\u54E1 \u85A9\u723E\u85A9\u821E \u8DF3\u821E \u8DF3\u821E\u5605\u5973\u4EBA \u9EC3\u76AE\u819A",
    "\u{1F483}\u{1F3FD}": "\u8DF3\u821E\u5605\u5973\u4EBA\uFF1A\u4E2D\u7B49\u76AE\u819A disco party \u4E2D\u7B49\u76AE\u819A \u4EBA\u7269 \u512A\u96C5 \u5973\u4EBA \u5973\u58EB \u5973\u6027 \u63A2\u6208 \u6CD5\u862D\u660E\u6B4C \u821E\u8E48\u54E1 \u85A9\u723E\u85A9\u821E \u8DF3\u821E \u8DF3\u821E\u5605\u5973\u4EBA",
    "\u{1F483}\u{1F3FE}": "\u8DF3\u821E\u5605\u5973\u4EBA\uFF1A\u4E2D\u6DF1\u76AE\u819A disco party \u4E2D\u6DF1\u76AE\u819A \u4EBA\u7269 \u512A\u96C5 \u5973\u4EBA \u5973\u58EB \u5973\u6027 \u63A2\u6208 \u6CD5\u862D\u660E\u6B4C \u821E\u8E48\u54E1 \u85A9\u723E\u85A9\u821E \u8DF3\u821E \u8DF3\u821E\u5605\u5973\u4EBA",
    "\u{1F483}\u{1F3FF}": "\u8DF3\u821E\u5605\u5973\u4EBA\uFF1A\u9ED1\u76AE\u819A disco party \u4EBA\u7269 \u512A\u96C5 \u5973\u4EBA \u5973\u58EB \u5973\u6027 \u63A2\u6208 \u6CD5\u862D\u660E\u6B4C \u821E\u8E48\u54E1 \u85A9\u723E\u85A9\u821E \u8DF3\u821E \u8DF3\u821E\u5605\u5973\u4EBA \u9ED1\u76AE\u819A",
    "\u{1F57A}": "\u8DF3\u821E\u5605\u7537\u4EBA disco party \u4EBA\u7269 \u512A\u96C5 \u63A2\u6208 \u6CD5\u862D\u660E\u6B4C \u7537\u4EBA \u7537\u58EB \u7537\u6027 \u821E\u8E48\u54E1 \u85A9\u723E\u85A9\u821E \u8DF3\u821E",
    "\u{1F57A}\u{1F3FB}": "\u8DF3\u821E\u5605\u7537\u4EBA\uFF1A\u767D\u76AE\u819A disco party \u4EBA\u7269 \u512A\u96C5 \u63A2\u6208 \u6CD5\u862D\u660E\u6B4C \u7537\u4EBA \u7537\u58EB \u7537\u6027 \u767D\u76AE\u819A \u821E\u8E48\u54E1 \u85A9\u723E\u85A9\u821E \u8DF3\u821E \u8DF3\u821E\u5605\u7537\u4EBA",
    "\u{1F57A}\u{1F3FC}": "\u8DF3\u821E\u5605\u7537\u4EBA\uFF1A\u9EC3\u76AE\u819A disco party \u4EBA\u7269 \u512A\u96C5 \u63A2\u6208 \u6CD5\u862D\u660E\u6B4C \u7537\u4EBA \u7537\u58EB \u7537\u6027 \u821E\u8E48\u54E1 \u85A9\u723E\u85A9\u821E \u8DF3\u821E \u8DF3\u821E\u5605\u7537\u4EBA \u9EC3\u76AE\u819A",
    "\u{1F57A}\u{1F3FD}": "\u8DF3\u821E\u5605\u7537\u4EBA\uFF1A\u4E2D\u7B49\u76AE\u819A disco party \u4E2D\u7B49\u76AE\u819A \u4EBA\u7269 \u512A\u96C5 \u63A2\u6208 \u6CD5\u862D\u660E\u6B4C \u7537\u4EBA \u7537\u58EB \u7537\u6027 \u821E\u8E48\u54E1 \u85A9\u723E\u85A9\u821E \u8DF3\u821E \u8DF3\u821E\u5605\u7537\u4EBA",
    "\u{1F57A}\u{1F3FE}": "\u8DF3\u821E\u5605\u7537\u4EBA\uFF1A\u4E2D\u6DF1\u76AE\u819A disco party \u4E2D\u6DF1\u76AE\u819A \u4EBA\u7269 \u512A\u96C5 \u63A2\u6208 \u6CD5\u862D\u660E\u6B4C \u7537\u4EBA \u7537\u58EB \u7537\u6027 \u821E\u8E48\u54E1 \u85A9\u723E\u85A9\u821E \u8DF3\u821E \u8DF3\u821E\u5605\u7537\u4EBA",
    "\u{1F57A}\u{1F3FF}": "\u8DF3\u821E\u5605\u7537\u4EBA\uFF1A\u9ED1\u76AE\u819A disco party \u4EBA\u7269 \u512A\u96C5 \u63A2\u6208 \u6CD5\u862D\u660E\u6B4C \u7537\u4EBA \u7537\u58EB \u7537\u6027 \u821E\u8E48\u54E1 \u85A9\u723E\u85A9\u821E \u8DF3\u821E \u8DF3\u821E\u5605\u7537\u4EBA \u9ED1\u76AE\u819A",
    "\u{1F574}\uFE0F": "\u7740\u4F4F\u897F\u88DD\u98C4\u6D6E\u5605\u7537\u4EBA \u4EBA\u7269 \u61F8\u6D6E \u696D\u52D9 \u7537\u4EBA \u7537\u58EB \u7537\u6027 \u7A7F\u8457\u897F\u88DD\u61F8\u6D6E\u7684\u7537\u58EB \u897F\u88DD",
    "\u{1F574}\u{1F3FB}": "\u7740\u4F4F\u897F\u88DD\u98C4\u6D6E\u5605\u7537\u4EBA\uFF1A\u767D\u76AE\u819A \u4EBA\u7269 \u61F8\u6D6E \u696D\u52D9 \u7537\u4EBA \u7537\u58EB \u7537\u6027 \u767D\u76AE\u819A \u7740\u4F4F\u897F\u88DD\u98C4\u6D6E\u5605\u7537\u4EBA \u7A7F\u8457\u897F\u88DD\u61F8\u6D6E\u7684\u7537\u58EB \u897F\u88DD",
    "\u{1F574}\u{1F3FC}": "\u7740\u4F4F\u897F\u88DD\u98C4\u6D6E\u5605\u7537\u4EBA\uFF1A\u9EC3\u76AE\u819A \u4EBA\u7269 \u61F8\u6D6E \u696D\u52D9 \u7537\u4EBA \u7537\u58EB \u7537\u6027 \u7740\u4F4F\u897F\u88DD\u98C4\u6D6E\u5605\u7537\u4EBA \u7A7F\u8457\u897F\u88DD\u61F8\u6D6E\u7684\u7537\u58EB \u897F\u88DD \u9EC3\u76AE\u819A",
    "\u{1F574}\u{1F3FD}": "\u7740\u4F4F\u897F\u88DD\u98C4\u6D6E\u5605\u7537\u4EBA\uFF1A\u4E2D\u7B49\u76AE\u819A \u4E2D\u7B49\u76AE\u819A \u4EBA\u7269 \u61F8\u6D6E \u696D\u52D9 \u7537\u4EBA \u7537\u58EB \u7537\u6027 \u7740\u4F4F\u897F\u88DD\u98C4\u6D6E\u5605\u7537\u4EBA \u7A7F\u8457\u897F\u88DD\u61F8\u6D6E\u7684\u7537\u58EB \u897F\u88DD",
    "\u{1F574}\u{1F3FE}": "\u7740\u4F4F\u897F\u88DD\u98C4\u6D6E\u5605\u7537\u4EBA\uFF1A\u4E2D\u6DF1\u76AE\u819A \u4E2D\u6DF1\u76AE\u819A \u4EBA\u7269 \u61F8\u6D6E \u696D\u52D9 \u7537\u4EBA \u7537\u58EB \u7537\u6027 \u7740\u4F4F\u897F\u88DD\u98C4\u6D6E\u5605\u7537\u4EBA \u7A7F\u8457\u897F\u88DD\u61F8\u6D6E\u7684\u7537\u58EB \u897F\u88DD",
    "\u{1F574}\u{1F3FF}": "\u7740\u4F4F\u897F\u88DD\u98C4\u6D6E\u5605\u7537\u4EBA\uFF1A\u9ED1\u76AE\u819A \u4EBA\u7269 \u61F8\u6D6E \u696D\u52D9 \u7537\u4EBA \u7537\u58EB \u7537\u6027 \u7740\u4F4F\u897F\u88DD\u98C4\u6D6E\u5605\u7537\u4EBA \u7A7F\u8457\u897F\u88DD\u61F8\u6D6E\u7684\u7537\u58EB \u897F\u88DD \u9ED1\u76AE\u819A",
    "\u{1F46F}": "\u5154\u5973\u90CE \u5154\u8033 \u5154\u8033\u4ED4 \u5973\u58EB \u5B56\u5973 \u5B56\u59B9 \u5B56\u751F\u5973 \u6D3E\u5C0D \u821E\u8E48\u54E1 \u8DF3\u821E \u96D9\u80DE\u80CE",
    "\u{1F46F}\u{1F3FB}": "\u5154\u5973\u90CE \u5154\u8033 \u5154\u8033\u4ED4 \u5973\u58EB \u5B56\u5973 \u5B56\u59B9 \u5B56\u751F\u5973 \u6D3E\u5C0D \u767D\u76AE\u819A \u821E\u8E48\u54E1 \u8DF3\u821E \u96D9\u80DE\u80CE",
    "\u{1F46F}\u{1F3FC}": "\u5154\u5973\u90CE \u5154\u8033 \u5154\u8033\u4ED4 \u5973\u58EB \u5B56\u5973 \u5B56\u59B9 \u5B56\u751F\u5973 \u6D3E\u5C0D \u821E\u8E48\u54E1 \u8DF3\u821E \u96D9\u80DE\u80CE \u9EC3\u76AE\u819A",
    "\u{1F46F}\u{1F3FD}": "\u5154\u5973\u90CE\uFF1A\u4E2D\u7B49\u76AE\u819A \u4E2D\u7B49\u76AE\u819A \u5154\u5973\u90CE \u5154\u8033 \u5154\u8033\u4ED4 \u5973\u58EB \u5B56\u5973 \u5B56\u59B9 \u5B56\u751F\u5973 \u6D3E\u5C0D \u821E\u8E48\u54E1 \u8DF3\u821E \u96D9\u80DE\u80CE",
    "\u{1F46F}\u{1F3FE}": "\u5154\u5973\u90CE\uFF1A\u4E2D\u6DF1\u76AE\u819A \u4E2D\u6DF1\u76AE\u819A \u5154\u5973\u90CE \u5154\u8033 \u5154\u8033\u4ED4 \u5973\u58EB \u5B56\u5973 \u5B56\u59B9 \u5B56\u751F\u5973 \u6D3E\u5C0D \u821E\u8E48\u54E1 \u8DF3\u821E \u96D9\u80DE\u80CE",
    "\u{1F46F}\u{1F3FF}": "\u5154\u5973\u90CE \u5154\u8033 \u5154\u8033\u4ED4 \u5973\u58EB \u5B56\u5973 \u5B56\u59B9 \u5B56\u751F\u5973 \u6D3E\u5C0D \u821E\u8E48\u54E1 \u8DF3\u821E \u96D9\u80DE\u80CE \u9ED1\u76AE\u819A",
