    "\u{1F318}": "\u6B98\u6708 \u4E0B\u5F26\u6708 \u592A\u7A7A \u5B87\u5B99 \u65B0\u6708 \u6708\u4EAE \u6708\u8755",
    "\u{1F319}": "\u4E0A\u5F26\u6708 \u592A\u7A7A \u5B87\u5B99 \u65B0\u6708 \u6708\u4EAE \u9F4B\u6212\u6708",
    "\u{1F31A}": "\u65B0\u6708\u5605\u9762\u5B54 \u592A\u7A7A \u5B87\u5B99 \u65B0\u6708 \u65B0\u6708\u81C9 \u6708\u4EAE \u6709\u81C9\u7684\u65B0\u6708 \u81C9\u5B54 \u9762\u5B54 \u9ED1\u6708\u4EAE \u9ED1\u9762",
    "\u{1F31B}": "\u4E0A\u5F26\u6708\u5605\u9762\u5B54 \u4E0A\u5F26\u6708 \u592A\u7A7A \u5B87\u5B99 \u5F4E\u6708 \u6708\u4EAE \u6708\u4EAE\u81C9 \u6708\u4EAE\u9762 \u81C9\u5B54",
    "\u{1F31C}": "\u4E0B\u5F26\u6708\u5605\u9762\u5B54 \u4E0B\u5F26\u6708 \u592A\u7A7A \u5B87\u5B99 \u5F4E\u6708 \u6708\u4EAE \u6708\u4EAE\u81C9 \u6708\u4EAE\u9762 \u81C9\u5B54",
    "\u{1F321}\uFE0F": "\u5929\u6C23 \u6EAB\u5EA6\u8A08",
    "\u2600\uFE0F": "\u5929\u6C23 \u592A\u7A7A \u592A\u967D \u597D\u5929\u6C23 \u5B87\u5B99 \u6674\u5929 \u967D\u5149",
    "\u{1F31D}": "\u6EFF\u6708\u5605\u9762\u5B54 \u592A\u7A7A \u5B87\u5B99 \u6708\u4EAE \u6708\u4EAE\u81C9 \u6708\u4EAE\u9762 \u6EFF\u6708 \u81C9\u5B54",
    "\u{1F31E}": "\u592A\u967D\u7B11\u9762 \u5929\u6C23 \u592A\u967D \u592A\u967D\u81C9 \u592A\u967D\u9762 \u65E5\u982D \u6674\u5929 \u6D77\u7058 \u71B1 \u81C9\u5B54 \u967D\u5149",
    "\u{1FA90}": "\u6709\u884C\u661F\u74B0\u7684\u884C\u661F \u571F\u661F \u571F\u661F\u74B0 \u661F\u7403 \u74B0\u72C0\u884C\u661F",
    "\u2B50": "\u5929\u6587 \u661F\u661F \u9583\u4EAE",
    "\u{1F31F}": "\u9583\u4EAE\u5605\u661F\u661F \u52DD\u5229 \u591C\u665A \u661F\u661F \u767C\u5149 \u9583\u4EAE \u9583\u8000 \u9583\u9583\u767C\u5149",
    "\u{1F320}": "\u4E00\u9583\u4E00\u9583 \u589C\u843D \u591C\u665A \u592A\u7A7A \u5B87\u5B99 \u661F\u661F \u665A\u4E0A \u6D41\u661F",
