    "\u{1F325}\uFE0F": "\u592A\u967D\u55BA\u4E00\u5927\u7247\u96F2\u5F8C\u9762 \u5929\u6C23 \u592A\u967D \u9670\u5929 \u9670\u6674\u4E0D\u5B9A \u96F2",
    "\u{1F326}\uFE0F": "\u592A\u967D\u55BA\u96E8\u96F2\u5F8C\u9762 \u4E0B\u96E8 \u5929\u6C23 \u592A\u967D \u6642\u6674\u6642\u96E8 \u843D\u96E8 \u9670\u6674\u4E0D\u5B9A \u96E8 \u96E8\u96F2 \u96F2",
    "\u{1F327}\uFE0F": "\u96E8\u96F2 \u4E0B\u96E8 \u5929\u6C23 \u843D\u96E8 \u96E8 \u96F2",
