    "\u{1F300}": "\u5927\u98A8 \u5929\u6C23 \u65CB\u8F49 \u65CB\u98A8 \u6688 \u982D\u6688 \u98B1\u98A8 \u9F8D\u6372\u98A8",
    "\u{1F308}": "\u540C\u6027\u6200 \u5929\u6C23 \u5973\u540C\u6027\u6200 \u5F69\u8679 \u6027\u5225\u9177\u5152 \u7537\u540C\u6027\u6200 \u8DE8\u6027\u5225 \u9177\u5152 \u96D9\u6027\u6200 \u9A55\u50B2",
