    "\u2602\uFE0F": "\u906E \u4E0B\u96E8 \u5098 \u96E8\u5098 \u96E8\u906E",
    "\u2614": "\u843D\u96E8 \u4E0B\u96E8 \u5098 \u5929\u6C23 \u906E \u96E8\u5098 \u96E8\u6C34 \u96E8\u6EF4 \u96E8\u906E \u96E8\u9EDE",
    "\u26F1\uFE0F": "\u6C99\u7058\u906E \u5098 \u592A\u967D \u592A\u967D\u5098 \u592A\u967D\u906E \u906E \u96E8 \u96E8\u5098 \u96E8\u906E",
    "\u26A1": "\u5371\u96AA \u6253\u96F7 \u81EA\u7136 \u884C\u96F7 \u9583\u96FB \u96F7 \u96F7\u96FB \u96FB \u96FB\u529B \u96FB\u58D3 \u9AD8\u96FB\u58D3",
    "\u2744\uFE0F": "\u51CD \u5929\u6C23 \u5BD2\u51B7 \u96EA \u96EA\u82B1",
    "\u2603\uFE0F": "\u4E0B\u96EA \u51CD \u5BD2\u51B7 \u843D\u96EA \u96EA \u96EA\u4EBA",
    "\u26C4": "\u4E0B\u96EA \u51CD \u5BD2\u51B7 \u843D\u96EA \u96EA \u96EA\u4EBA",
    "\u2604\uFE0F": "\u592A\u7A7A \u5B87\u5B99 \u5F57\u661F",
    "\u{1F525}": "\u706B \u706B\u7130 \u71B1 \u71C3\u71D2",
    "\u{1F4A7}": "\u5929\u6C23 \u5BD2\u51B7 \u6C34 \u6C34\u6EF4 \u6C34\u9EDE \u6C57\u6C34 \u773C\u6DDA \u81EA\u7136 \u96E8\u6EF4",
    "\u{1F30A}": "\u6D77\u6D6A \u6C34 \u6C34\u6CE2 \u6CE2\u6D6A \u6D77\u6C34 \u6D77\u6D0B \u81EA\u7136 \u885D\u6D6A",
    "\u{1F453}": "\u670D\u88DD \u773C\u775B \u773C\u93E1 \u8001\u82B1 \u8FD1\u8996 \u9060\u8996",
    "\u{1F576}\uFE0F": "\u592A\u967D\u773C\u93E1 \u773C\u775B \u773C\u93E1 \u58A8\u93E1",
    "\u{1F97D}": "\u6E38\u6CF3 \u6F5B\u6C34 \u710A\u5DE5 \u710A\u63A5 \u86D9\u93E1 \u8B77\u76EE\u93E1 \u8B77\u773C\u7F69",
    "\u{1F97C}": "\u5BE6\u9A57\u5BA4\u5916\u5957 \u670D\u88DD \u767D\u888D \u79D1\u5B78\u5BB6 \u8863\u670D \u91AB\u751F",
    "\u{1F9BA}": "\u53CD\u5149\u80CC\u5FC3 \u5B89\u5168 \u7DCA\u6025 \u80CC\u5FC3 \u87A2\u5149\u80CC\u5FC3",
    "\u{1F454}": "\u9818\u5454 \u53D7\u50F1 \u54E1\u5DE5 \u5DE5\u4F5C \u670D\u88DD \u8863\u670D \u88C7\u886B \u896F\u886B \u8A8D\u771F \u9818\u5E36",
    "\u{1F455}": "polo tee T\u5379 T\u6064 T\u88C7 \u4F11\u9592 \u4FBF\u88DD \u670D\u88DD \u7FFB\u9818 \u85CD\u8272 \u8863\u670D \u896F\u886B \u8CFC\u7269 \u9031\u672B",
    "\u{1F456}": "\u4F11\u9592 \u670D\u88DD \u725B\u4ED4\u5E03 \u725B\u4ED4\u8932 \u85CD\u8272 \u8863\u670D \u8932\u5B50 \u8CFC\u7269 \u9031\u672B",
    "\u{1F9E3}": "\u9838\u5DFE \u570D\u5DFE \u5BD2\u51B7 \u6346\u7D81 \u7DA0\u8272",
    "\u{1F9E4}": "\u624B \u624B\u5957 \u624B\u896A \u85CD\u8272",
    "\u{1F9E5}": "\u5927\u8938 \u51CD \u5916\u5957 \u5927\u8863 \u593E\u514B \u5BD2\u51B7 \u7D05\u8272 \u7FBD\u7D68 \u8938",
    "\u{1F9E6}": "\u77ED\u896A \u85CD\u8272 \u896A\u5B50 \u9577\u896A",
