    "\u{1F458}": "yukata \u548C\u670D \u670D\u88DD \u6D74\u8863 \u8212\u9069 \u8863\u670D",
    "\u{1F97B}": "\u838E\u9E97 \u5370\u5EA6 \u670D\u88DD \u7D17\u9E97 \u8863\u670D \u88D9 \u9023\u8863\u88D9",
    "\u{1FA71}": "\u4E00\u4EF6\u5F0F\u6CF3\u8863 \u4E00\u4EF6\u982D\u6CF3\u8863 \u6CF3\u8863 \u9023\u9AD4\u6CF3\u8863",
    "\u{1FA72}": "\u4E00\u4EF6\u5F0F \u4E09\u89D2\u8932 \u5167\u8932 \u5E95\u8932 \u6CF3\u8863 \u6CF3\u8932",
    "\u{1FA73}": "\u77ED\u8932 \u5167\u8863 \u5E95\u8932 \u6CF3\u8863 \u6CF3\u8932 \u8932 \u8932\u5B50",
    "\u{1F459}": "\u6BD4\u5805\u5C3C sexy \u4E09\u9EDE\u5F0F \u5169\u4EF6\u5F0F \u592A\u967D \u6027\u611F \u65E5\u5149\u6D74 \u6C99\u7058 \u6CF3\u8863 \u6D77\u7058 \u6E38\u6C34 \u6E38\u6CF3",
    "\u{1F45A}": "\u4E0A\u8863 \u5973\u6027 \u670D\u88DD \u7C89\u7D05 \u8863\u670D \u88C7\u886B \u896F\u886B",
    "\u{1FAAD}": "\u50B3\u7D71 \u548C\u98A8 \u6247 \u6247\u5B50 \u647A\u758A\u624B\u6247 \u64A5\u6247 \u65E5\u672C \u71B1 \u7D19\u6247 \u821E\u8E48",
    "\u{1F45B}": "\u9280\u5305 \u6253\u626E \u670D\u88DD \u786C\u5E63 \u7C89\u7D05 \u7D05\u8272 \u8377\u5305 \u8863\u670D \u8CFC\u7269 \u9322\u5305",
    "\u{1F45C}": "\u624B\u888B \u5305\u5305 \u5973\u58EB \u624B\u63D0\u5305 \u670D\u88DD \u76AE\u5305 \u8863\u670D \u8CFC\u7269 \u9280\u5305 \u9322\u5305",
    "\u{1F45D}": "\u624B\u63D0\u5305 \u624B\u888B \u670D\u88DD \u8863\u670D \u9280\u5305 \u9322\u5305",
    "\u{1F6CD}\uFE0F": "\u888B\u5B50 \u8CFC\u7269 \u8CFC\u7269\u888B \u9152\u5E97",
    "\u{1F392}": "\u5B78\u6821 \u6559\u80B2 \u66F8\u5305 \u80CC\u5305 \u80CC\u56CA",
    "\u{1FA74}": "\u4EBA\u5B57\u62D6 \u62D6\u978B \u6C99\u7058 \u6DBC\u978B \u978B",
    "\u{1F45E}": "oxford \u5561\u8272 \u5B78\u751F \u670D\u88DD \u7537\u88DD \u76AE\u978B \u8173 \u8863\u670D \u8910\u8272 \u8E22 \u978B",
    "\u{1F45F}": "\u6CE2\u978B \u670D\u88DD \u7DB2\u7403 \u8863\u670D \u8CFC\u7269 \u8DD1\u6B65 \u8DD1\u978B \u8E22 \u904B\u52D5 \u904B\u52D5\u978B \u978B",
    "\u{1F97E}": "\u5561\u8272 \u5F92\u6B65\u65C5\u884C \u6236\u5916 \u65C5\u884C\u978B \u767B\u5C71\u9774 \u76AE\u9774 \u77ED\u9774 \u80CC\u5305 \u80CC\u5305\u65C5\u884C \u884C\u5C71 \u8910\u8272 \u9060\u8DB3 \u9732\u71DF \u9774\u5B50 \u978B",
    "\u{1F97F}": "\u5E73\u5E95\u978B \u7DA0\u8272 \u82AD\u857E\u5E73\u5E95\u978B \u978B",
    "\u{1F460}": "\u9AD8\u8E2D\u978B \u5973\u6027 \u5973\u88DD\u978B \u6642\u5C1A \u670D\u88DD \u8863\u670D \u8CFC\u7269 \u978B \u9AD8\u8DDF\u978B",
    "\u{1F461}": "\u539A\u5E95\u978B \u5973\u6027 \u6DBC\u978B \u978B \u9AD8\u8E2D\u978B \u9B06\u7CD5\u978B",
    "\u{1FA70}": "\u821E\u8E48 \u82AD\u857E\u821E \u82AD\u857E\u821E\u978B \u8DF3\u821E \u978B",
