    "\u{1FAAE}": "\u53C9\u68B3 \u68B3 \u68B3\u5B50 \u68B3\u982D \u7F8E\u9AEE \u982D\u9AEE \u9AEE\u578B",
    "\u{1F451}": "\u52DD\u5229 \u570B\u738B \u5973\u738B \u670D\u88DD \u7687\u51A0 \u7687\u5BA4",
    "\u{1F452}": "\u5973\u6027 \u5E3D\u5B50 \u670D\u88DD \u82B1\u5712 \u8349\u5E3D \u8863\u670D",
    "\u{1F3A9}": "\u5E3D\u5B50 \u670D\u88DD \u79AE\u5E3D \u7D33\u58EB\u5E3D \u8863\u670D \u9AD8\u5E3D \u9AD8\u9802\u79AE\u5E3D \u9B54\u8853 \u9B54\u8853\u5E2B\u5E3D",
    "\u{1F393}": "\u535A\u58EB \u5B78\u8005 \u5E3D\u5B50 \u6559\u80B2 \u65B9\u5E3D \u670D\u88DD \u7562\u696D \u7562\u696D\u5E3D \u78A9\u58EB \u9AD8\u7B49\u6559\u80B2",
    "\u{1F9E2}": "\u68D2\u7403\u5E3D cap\u5E3D \u7DA0\u5E3D \u9D28\u5634\u5E3D",
    "\u{1FA96}": "\u58EB\u5175 \u6230\u722D \u6B65\u5175 \u8ECD\u4E8B \u8ECD\u968A \u982D\u76D4",
    "\u26D1\uFE0F": "\u5B89\u5168\u5E3D \u5341\u5B57 \u5E3D\u5B50 \u63F4\u52A9 \u6551\u63F4\u4EBA\u54E1 \u6551\u8B77 \u91AB\u8B77 \u982D\u76D4",
    "\u{1F4FF}": "\u9838\u93C8 \u5B97\u6559 \u5FF5\u73E0 \u670D\u88DD \u73E0\u5B50 \u7948\u79B1 \u9838\u934A \u9996\u98FE",
    "\u{1F484}": "\u5507\u818F \u5316\u599D \u5316\u599D\u54C1 \u7D04\u6703 \u7D05\u8272",
    "\u{1F48D}": "\u5A5A\u79AE \u6212\u6307 \u6C42\u5A5A \u6D6A\u6F2B \u767C\u5149 \u7D50\u5A5A \u8A02\u5A5A \u947D\u77F3 \u9583\u4EAE",
    "\u{1F48E}": "\u5A5A\u79AE \u5BF6\u77F3 \u6D6A\u6F2B \u73E0\u5BF6 \u7D50\u5A5A \u8A02\u5A5A \u947D\u77F3",
    "\u{1F507}": "\u5587\u53ED \u5B89\u975C \u63DA\u8072\u5668 \u8072\u97F3 \u95DC\u6389\u5587\u53ED \u975C\u97F3 \u97F3\u97FF",
    "\u{1F508}": "\u7D30\u8072\u5587\u53ED \u5587\u53ED \u5C0F\u8072 \u63DA\u8072\u5668 \u67D4\u548C \u7D30\u8072 \u8072\u97F3 \u97F3\u6A02 \u97F3\u91CF \u97F3\u97FF",
    "\u{1F509}": "\u8072\u91CF\u4E2D\u7B49\u5605\u5587\u53ED \u4E2D\u97F3\u91CF \u5587\u53ED \u63DA\u8072\u5668 \u8072\u91CF\u4E2D\u7B49 \u8072\u97F3 \u97F3\u6A02 \u97F3\u91CF \u97F3\u97FF",
    "\u{1F50A}": "\u8072\u91CF\u5927\u5605\u5587\u53ED \u5587\u53ED \u5927\u8072 \u63DA\u8072\u5668 \u8072\u97F3 \u97F3\u6A02 \u97F3\u91CF \u97F3\u97FF \u9AD8\u97F3\u91CF",
    "\u{1F4E2}": "annoucement siren \u516C\u5171\u5EE3\u64AD \u5587\u53ED \u5927\u8072\u516C \u63DA\u8072\u5668 \u64F4\u97F3\u5668 \u6CE8\u610F \u6D88\u606F \u8072\u97F3 \u8B66\u5831 \u901A\u8A0A \u97FF\u8072",
    "\u{1F4E3}": "\u50B3\u8072\u7B52 \u5587\u53ED \u5927\u8072\u516C \u64F4\u97F3\u5668 \u6B61\u547C \u8072\u97F3",
